export const isOutOfViewport = (left, top, tooltipRect, bodyRect) => {
    if (left < 0) {
        return true;
    }
    if (top < 0) {
        return true;
    }
    if (left + tooltipRect.width > bodyRect.width) {
        return true;
    }
    if (top + tooltipRect.height > bodyRect.height) {
        return true;
    }
    return false;
};
